      ['실수로 지운 사진을 되살릴 수 있나요?', '갤러리 휴지통에 30일 동안 남아 있어요. 휴지통을 비웠거나 기간이 지났다면 되살리기 어려워요. 자세한 순서는 <a href="/guides/galaxy-recover-deleted-photos/">갤럭시에서 지운 사진, 휴지통이 두 곳일 수 있어요</a>에 정리해 두었어요.']
