    desc: '간판의 전화번호나 종이에 적힌 주소를 손으로 옮겨 적지 않아도 돼요. 아이폰 카메라와 사진 앱에서 글자를 골라 복사하는 법, 버튼이 안 보일 때 확인할 설정을 알려 드려요.',
    time: '5분', published: '2026-10-29', modified: '2026-10-29', reviewed: '2026-10-29', checked: 'Apple 공식 iPhone 사용 설명서 iOS 27판을 기준으로 정리했어요.',
    lead: '안내문에 적힌 계좌번호나 긴 주소를 휴대폰에 하나하나 다시 쳐 넣고 있다면 라이브 텍스트를 써 보세요. 아이폰은 카메라 화면이나 사진에 찍힌 글자를 알아보고, 그 글자를 손가락으로 골라 복사할 수 있게 해 줘요. 전화번호가 찍혀 있으면 화면 아래 버튼으로 바로 전화를 걸 수도 있어요.',
