    "extra": "<section><h2>지금 상태에 맞춰 다음 단계를 골라요</h2><div class=\"table-scroll\"><table><caption>집중 모드 점검 순서</caption><thead><tr><th>확인한 상태</th><th>다음 행동</th></tr></thead><tbody><tr><td>방해금지 또는 다른 모드가 켜짐</td><td>현재 모드를 끄고 새 알림으로 비교</td></tr><tr><td>일정한 시간에 다시 켜짐</td><td>해당 모드의 일정·자동 활성화 조건 확인</td></tr><tr><td>모드는 쓰되 특정 연락을 받고 싶음</td><td>사람·앱의 허용 또는 무음 목록 확인</td></tr><tr><td>집중 모드를 꺼도 변화가 없음</td><td>특정 앱인지 전체 소리 문제인지 구분</td></tr></tbody></table></div><h2>설정을 마치기 전 확인할 것</h2><ul class=\"checklist\"><li>바꾼 집중 모드 이름을 확인했나요?</li><li>불필요한 자동 일정만 조정했나요?</li><li>필요한 사람과 앱을 반대로 무음 처리하지 않았나요?</li><li>변경 후 새 알림으로 차이를 확인했나요?</li></ul></section>",
