  "extra": "<section><h2>문제에 따라 먼저 할 일</h2><div class=\"table-scroll\"><table><caption>Windows 인쇄 대기열이 멈췄을 때 확인 순서</caption><thead><tr><th>보이는 상태</th><th>먼저 할 일</th></tr></thead><tbody><tr><td>문서 하나만 ‘인쇄 중’에 멈춤</td><td>올바른 프린터 대기열인지 확인 → 해당 작업만 취소</td></tr><tr><td>취소를 눌러도 ‘삭제 중’으로 남음</td><td>프린터와 연결 확인 → 프린터 전원을 다시 켜기</td></tr><tr><td>대기열의 모든 문서가 멈춤</td><td>도움말 보기 문제 해결사 → 인쇄 스풀러 다시 시작</td></tr><tr><td>서비스를 다시 시작해도 계속 멈춤</td><td>마지막 방법으로 스풀러 파일 삭제와 서비스 재시작</td></tr></tbody></table></div><h2>파일을 직접 지우기 전에</h2><ul class=\"checklist\"><li>대기열에 남은 모든 인쇄 작업이 취소될 수 있어요. 다시 출력해야 할 문서는 원본 파일을 열어 다시 보내야 합니다.</li><li>삭제 대상은 인쇄 대기열 폴더 안의 파일입니다. 폴더 자체나 다른 경로의 파일은 삭제하지 마세요.</li><li>공유 프린터와 회사·학교 PC는 관리자나 다른 사용자의 작업에 영향을 줄 수 있으니 먼저 확인하세요.</li><li>문서가 프린터에서 이미 출력되기 시작했다면 PC에서 취소해도 현재 용지가 나올 수 있어요.</li></ul></section>",
